(6710875, 1003790, 113156, '<td valign="top">Living a naturel life, a photo that makes us feel good.</td>', 'Living a naturel life, a photo that makes us feel good.', '2012-03-15 08:54:47.000000', NULL, 1),
(6710885, 1004546, 16148, '<td valign="top">Amazing catch!  Probably my favorite in the challenge and I''ve just started voting.  The bottom crop is a little unusual but seems to work fine.  Having the car touch the frame edge brings it closer to the viewer and maybe that''s part of what you wanted.</td>', 'Amazing catch!  Probably my favorite in the challenge and I''ve just started voting.  The bottom crop is a little unusual but seems to work fine.  Having the car touch the frame edge brings it closer to the viewer and maybe that''s part of what you wanted.', '2012-03-15 09:01:11.000000', NULL, 1),
(6710887, 1004616, 16148, '<td valign="top">This is a beautiful image.  Thanks</td>', 'This is a beautiful image.  Thanks', '2012-03-15 09:01:36.000000', NULL, 1),
(6710891, 1003047, 113156, '<td valign="top">Naturally Art, why complicate things, a very fine image.</td>', 'Naturally Art, why complicate things, a very fine image.', '2012-03-15 09:03:20.000000', NULL, 1),
(6710895, 1002155, 16148, '<td valign="top">Interesting shot and I like your processing.  The repeating shapes of spread fingers and roots is intriguing.</td>', 'Interesting shot and I like your processing.  The repeating shapes of spread fingers and roots is intriguing.', '2012-03-15 09:05:09.000000', NULL, 1),
(6710897, 1002371, 16148, '<td valign="top">Nicely done.</td>', 'Nicely done.', '2012-03-15 09:05:34.000000', NULL, 1),
