(6710939, 1001985, 110108, '<td valign="top">beautiful colors</td>', 'beautiful colors', '2012-03-15 09:46:28.000000', NULL, 1),
(6710971, 1004490, 113156, '<td valign="top">This is great, a scene conducted by art itself, a totally splendid and joyful photograph. 10 and a fav.</td>', 'This is great, a scene conducted by art itself, a totally splendid and joyful photograph. 10 and a fav.', '2012-03-15 10:11:38.000000', NULL, 1),
(6710988, 1004236, 110108, '<td valign="top">beautiful image</td>', 'beautiful image', '2012-03-15 10:24:06.000000', NULL, 1),
(6710996, 1002553, 93421, '<td valign="top">Personally my favourite image of the challenge.  Must say that the dark bit at the bottom of the image is distracting to me and draws my eye down.  Otherwise a simply stunning image.  Would gladly hang this on my wall.  Good luck</td>', 'Personally my favourite image of the challenge.  Must say that the dark bit at the bottom of the image is distracting to me and draws my eye down.  Otherwise a simply stunning image.  Would gladly hang this on my wall.  Good luck', '2012-03-15 10:26:37.000000', NULL, 1),
(6711039, 1004403, 138253, '<td valign="top">Nice composition on the shot!</td>', 'Nice composition on the shot!', '2012-03-15 10:51:05.000000', NULL, 1),
(6711042, 1004461, 138253, '<td valign="top">Looks like the Griswolds.. :)</td>', 'Looks like the Griswolds.. :)', '2012-03-15 10:51:44.000000', NULL, 1),
(6711055, 1004497, 138253, '<td valign="top">The offset angle is perfect for a carnival-y picture :)</td>', 'The offset angle is perfect for a carnival-y picture :)', '2012-03-15 10:55:24.000000', NULL, 1),
(6711068, 1003952, 138253, '<td valign="top">Interesting concept, but Dorthy''s leg detracts a bit from the picture when contrasted to the polished metal. Perhaps some nylons or airbrushing? Still getting good marks for concept :)</td>', 'Interesting concept, but Dorthy''s leg detracts a bit from the picture when contrasted to the polished metal. Perhaps some nylons or airbrushing? Still getting good marks for concept :)', '2012-03-15 11:00:01.000000', NULL, 1),
(6711069, 1004546, 43463, '<td valign="top">Voted earlier coming back to comment.<br/> <br/>Absolutely LOVE the mood and capture of meaning in this photo. The car has always been a symbol of freedom and spirit of adventure. It is a means to get from one place to another. The juxtaposition of the car next to the man in the wheelchair speaks to me that he has the means to be free from any limitations life sets upon him and the ability to set out on an adventure wherever he sets his mind to. Where there is a strong will and a means of travel there is a way to get to your destination. I really hope to see this in the top 5. Spectacular capture and the B&amp;W processing is just stunning (10).</td>', 'Voted earlier coming back to comment. Absolutely LOVE the mood and capture of meaning in this photo. The car has always been a symbol of freedom and spirit of adventure. It is a means to get from one place to another. The juxtaposition of the car next to the man in the wheelchair speaks to me that he has the means to be free from any limitations life sets upon him and the ability to set out on an adventure wherever he sets his mind to. Where there is a strong will and a means of travel there is a way to get to your destination. I really hope to see this in the top 5. Spectacular capture and the B&W processing is just stunning (10).', '2012-03-15 11:00:26.000000', NULL, 1),
(6711071, 1003218, 138253, '<td valign="top">The title alone made me laugh out loud at work, had to share with my with my coworkers :)</td>', 'The title alone made me laugh out loud at work, had to share with my with my coworkers :)', '2012-03-15 11:01:05.000000', NULL, 1);
