(6711779, 1004568, 40391, '<td valign="top">I almost missed the lone figure at the rear.  A great inclusion for a wonderful image.</td>', 'I almost missed the lone figure at the rear.  A great inclusion for a wonderful image.', '2012-03-15 21:06:36.000000', NULL, 1),
(6711784, 1004532, 43463, '<td valign="top">Great juxtaposition here. The door opens and the man emerges from the dark interior - as if he is moving into the light. To me, it speaks that he is emerging from the dark past of how Blacks were once horribly treated and now moves out into the open, to freedom and new possiblities. I also like how the composition is not divided half and half but the white door occupies 60% - it is as if the light is overtaking the dark as how the dawn dispells the night. I see it as symbolic of new opportunities that are dawning as the door swings open.</td>', 'Great juxtaposition here. The door opens and the man emerges from the dark interior - as if he is moving into the light. To me, it speaks that he is emerging from the dark past of how Blacks were once horribly treated and now moves out into the open, to freedom and new possiblities. I also like how the composition is not divided half and half but the white door occupies 60% - it is as if the light is overtaking the dark as how the dawn dispells the night. I see it as symbolic of new opportunities that are dawning as the door swings open.', '2012-03-15 21:09:23.000000', NULL, 1),
(6711785, 1002524, 40391, '<td valign="top">This is a truly beautiful image!  I particularly love the soft colours and image grain.  Very well composed.  Well done!</td>', 'This is a truly beautiful image!  I particularly love the soft colours and image grain.  Very well composed.  Well done!', '2012-03-15 21:09:27.000000', NULL, 1),
(6711793, 1004118, 40391, '<td valign="top">Hauntingly wonderful!</td>', 'Hauntingly wonderful!', '2012-03-15 21:14:09.000000', NULL, 1),
(6711801, 1003862, 124982, '<td valign="top">Absolutely beautiful capture of the storm. Love the "streaking" in the sky, and the mountains in the background are such a nice surprise! Wonder if the clouds were burned a little if it would add to the impact/emphasis of the storm? Still, great image!</td>', 'Absolutely beautiful capture of the storm. Love the "streaking" in the sky, and the mountains in the background are such a nice surprise! Wonder if the clouds were burned a little if it would add to the impact/emphasis of the storm? Still, great image!', '2012-03-15 21:18:50.000000', NULL, 1),
