(6717971, 1002553, 127081, '<td valign="top">nice natural frame.. texture...</td>', 'nice natural frame.. texture...', '2012-03-20 23:13:01.000000', NULL, 1),
(6717983, 1003688, 29011, '<td valign="top">Natural light? the lighting is nice and the slight desat works. I like how balanced the composition is though at other viewings think the flowers and greenery take up a lot of the central attention. (only commenting, no vote)</td>', 'Natural light? the lighting is nice and the slight desat works. I like how balanced the composition is though at other viewings think the flowers and greenery take up a lot of the central attention. (only commenting, no vote)', '2012-03-20 23:20:27.000000', NULL, 1),
(6717993, 1002867, 29011, '<td valign="top">Gotta love the point of view and leading lines in the shot. The lomo type colors are pretty neat too. The only pitty is the resizing(and/or)sharpening method produced those jagged edges along the bridge cables. (only commenting, no vote)</td>', 'Gotta love the point of view and leading lines in the shot. The lomo type colors are pretty neat too. The only pitty is the resizing(and/or)sharpening method produced those jagged edges along the bridge cables. (only commenting, no vote)', '2012-03-20 23:25:55.000000', NULL, 1),
(6718054, 1003734, 60862, '<td valign="top">Really milking this setting, eh, Karen? :)  But I have to say, it''s another beautiful shot of this beautiful architecture!  I think I like the flowers in color better than B&amp;W.  And of course, I''m not one to talk about using the same staircase repeatedly. :)</td>', 'Really milking this setting, eh, Karen? :)  But I have to say, it''s another beautiful shot of this beautiful architecture!  I think I like the flowers in color better than B&W.  And of course, I''m not one to talk about using the same staircase repeatedly. :)', '2012-03-20 23:46:08.000000', NULL, 1),
(6718058, 1003750, 60862, '<td valign="top">Wow, cool perspective! I didn''t know what that was, then read the title, then realized that the shape was a snail. :)</td>', 'Wow, cool perspective! I didn''t know what that was, then read the title, then realized that the shape was a snail. :)', '2012-03-20 23:47:51.000000', NULL, 1),
