(6719195, 1004118, 97225, '<td valign="top">Does that mean if I stay away from it I''ll be okay? <br/>Very evocative and the colours ar lovely.</td>', 'Does that mean if I stay away from it I''ll be okay? Very evocative and the colours ar lovely.', '2012-03-21 18:21:03.000000', NULL, 1),
(6719196, 1003687, 97225, '<td valign="top">I love the softness and the model is gorgeous.</td>', 'I love the softness and the model is gorgeous.', '2012-03-21 18:22:36.000000', NULL, 1),
(6719197, 1004103, 97225, '<td valign="top">Beautiful! It would be even without the butterfly and flower, but they make such a lovely subject against all that muted bokeh.</td>', 'Beautiful! It would be even without the butterfly and flower, but they make such a lovely subject against all that muted bokeh.', '2012-03-21 18:26:20.000000', NULL, 1),
(6719201, 1002632, 97225, '<td valign="top">Beautiful soft portrait.</td>', 'Beautiful soft portrait.', '2012-03-21 18:28:58.000000', NULL, 1),
(6719211, 1004655, 97225, '<td valign="top">Gorgeous shot!</td>', 'Gorgeous shot!', '2012-03-21 18:40:48.000000', NULL, 1),
(6719212, 1002270, 51747, '<td valign="top">Nice HDR image. I stayed at the Jerome Hotel one night ...and survived!</td>', 'Nice HDR image. I stayed at the Jerome Hotel one night ...and survived!', '2012-03-21 18:41:42.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6719214, 1003688, 97225, '<td valign="top">Beautiful still life, very artistic in the arrangement and in the photography.</td>', 'Beautiful still life, very artistic in the arrangement and in the photography.', '2012-03-21 18:42:02.000000', NULL, 1),
