(6721506, 1002524, 102278, '<td valign="top">Absolutely stunning photograph. Beautiful.</td>', 'Absolutely stunning photograph. Beautiful.', '2012-03-23 18:30:45.000000', NULL, 0),
(6721541, 1004655, 12253, '<td valign="top">Superb sky, superb landscape. I only wish the town lights didn''t bleed so much into the darker parts of the center mountains.  Deserves to be a 36x12 on your living room wall!</td>', 'Superb sky, superb landscape. I only wish the town lights didn''t bleed so much into the darker parts of the center mountains.  Deserves to be a 36x12 on your living room wall!', '2012-03-23 19:20:44.000000', NULL, 0),
(6721543, 1004569, 12253, '<td valign="top">I love the surreal feel of this, particularly the tree and the ground.</td>', 'I love the surreal feel of this, particularly the tree and the ground.', '2012-03-23 19:21:28.000000', NULL, 0),
(6721544, 1003786, 12253, '<td valign="top">Beautiful textures and light!</td>', 'Beautiful textures and light!', '2012-03-23 19:21:52.000000', NULL, 0),
