INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6721604, 1002281, 50695, '<td valign="top">brilliant. this wasn''t judged as a complete work of art from construction to photography. I''m very impressed.</td>', 'brilliant. this wasn''t judged as a complete work of art from construction to photography. I''m very impressed.', '2012-03-23 21:03:28.000000', NULL, 0),
(6721618, 1002630, 100831, '<td valign="top">It looks as if I need to add Salton Sea to my list of hopeful visits. Thanks for both the image and the notes. Excellent.</td>', 'It looks as if I need to add Salton Sea to my list of hopeful visits. Thanks for both the image and the notes. Excellent.', '2012-03-23 21:25:20.000000', NULL, 0),
(6721626, 1004019, 50695, '<td valign="top">I like this more the more I look at it.</td>', 'I like this more the more I look at it.', '2012-03-23 21:30:12.000000', NULL, 0),
(6721628, 1004546, 32997, '<td valign="top">fantastic!</td>', 'fantastic!', '2012-03-23 21:32:46.000000', NULL, 0),
(6721641, 1002524, 123833, '<td valign="top">This image without the man would be nothing! Just a bit of good PP.<br/>Congrats on the Jury Award! Very well deserved.<br/> <br/>PS This could be misunderstood. What I meant is that the man is the key to this image.<br/><br/><i>Message edited by author 2012-03-23 22:02:34.</i></td>', 'This image without the man would be nothing! Just a bit of good PP.Congrats on the Jury Award! Very well deserved. PS This could be misunderstood. What I meant is that the man is the key to this image.', '2012-03-23 21:58:56.000000', '2012-03-23 22:02:34.000000', 0),
(6721692, 1001906, 16106, '<td valign="top">"The light was all an advertisement board around the area and it got interesting."<br/>You are a master of understatement, this light is frickin awesome. Beautiful capture.</td>', '"The light was all an advertisement board around the area and it got interesting."You are a master of understatement, this light is frickin awesome. Beautiful capture.', '2012-03-23 23:17:20.000000', NULL, 0),
(6721717, 1004092, 11769, '<td valign="top">Wonderful composition, love how it works abstractly.</td>', 'Wonderful composition, love how it works abstractly.', '2012-03-24 00:09:34.000000', NULL, 0),
(6721718, 1002632, 11769, '<td valign="top">Gorgeous light. Beautiful and delicate.</td>', 'Gorgeous light. Beautiful and delicate.', '2012-03-24 00:12:57.000000', NULL, 0),
(6721736, 1004331, 11769, '<td valign="top">Love how everything has been reduced to a pattern.</td>', 'Love how everything has been reduced to a pattern.', '2012-03-24 01:26:15.000000', NULL, 0),
(6721738, 1004546, 117534, '<td valign="top">I keep comming back and reviewing this image.. In my book thats the sign of great art, the viewer wanting to see it time and time again!</td>', 'I keep comming back and reviewing this image.. In my book thats the sign of great art, the viewer wanting to see it time and time again!', '2012-03-24 01:37:21.000000', NULL, 0),
(6721747, 1002281, 30364, '<td valign="top">Inevitably undervalued.  A community of digital camera anoraks is hardly the place for something as adventurous and considered as this.  I came to realise that my initial instinct to try to separate the photography from the art was not only futile, it was also absurd.  I was tapping my foot to entirely the wrong beat.  You have taken Magritte beyond his own reach, but maybe that''s because you were born a bit later.<br/> <br/>Thanks for shaking that tree.<br/> <br/>I think I''m done with giving these things out now, but I had this one still about the shop, so I''d like you to have it ... <br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=800078" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/30000-34999/30364/120/Copyrighted_Image_Reuse_Prohibited_800078.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/30000-34999/30364/120/Copyrighted_Image_Reuse_Prohibited_800078.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/30000-34999/30364/120/Copyrighted_Image_Reuse_Prohibited_800078.jpg"/></a><br/><br/><i>Message edited by author 2012-03-24 03:09:01.</i></td>', 'Inevitably undervalued.  A community of digital camera anoraks is hardly the place for something as adventurous and considered as this.  I came to realise that my initial instinct to try to separate the photography from the art was not only futile, it was also absurd.  I was tapping my foot to entirely the wrong beat.  You have taken Magritte beyond his own reach, but maybe that''s because you were born a bit later. Thanks for shaking that tree. I think I''m done with giving these things out now, but I had this one still about the shop, so I''d like you to have it ... ', '2012-03-24 02:54:46.000000', '2012-03-24 03:09:01.000000', 0),
(6721769, 1004490, 114285, '<td valign="top">Yes Vlado well deserved. Outstanding in many ways.</td>', 'Yes Vlado well deserved. Outstanding in many ways.', '2012-03-24 06:31:56.000000', NULL, 0),
